INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('95685789-9268-401c-9e59-607b17b3b921','9','geografie-fizica','published',1,121,1783400000000,1783400000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('95685789-9268-401c-9e59-607b17b3b921','ro','Ce concluzie corectă tragem din faptul că uscatul ocupă 40% în emisfera nordică, dar doar 19% în cea sudică?','["Că uscatul este repartizat egal pe întreaga planetă.","Că uscatul este concentrat mai ales în emisfera nordică, numită de aceea și emisfera continentelor.","Că emisfera sudică nu are deloc uscat.","Că oceanele lipsesc cu totul din emisfera nordică."]','Compară cele două procente și vezi unde se adună uscatul. Fiindcă în nord se află de peste două ori mai mult uscat, emisfera nordică este numită și emisfera continentelor.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('7e96e9c7-bc6a-4b89-8056-eec33cd702b5','9','geografie-fizica','published',2,122,1783400000000,1783400000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('7e96e9c7-bc6a-4b89-8056-eec33cd702b5','ro','Care este cel mai adânc punct de pe Terra și în ce ocean se află?','["Fosa Puerto Rico, în Oceanul Indian.","Marea Moartă, în Oceanul Atlantic.","Fosa Marianelor, în Oceanul Pacific.","Fosa Java, în Oceanul Arctic."]','Cel mai adânc loc este în cel mai mare și mai adânc ocean. Fosa Marianelor, din Pacific, coboară până la circa −11 022 m, adâncimea record a planetei.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('88ee8b69-40f1-422f-9725-b374a1968c14','9','geografie-fizica','published',0,123,1783400000000,1783400000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('88ee8b69-40f1-422f-9725-b374a1968c14','ro','Marea Moartă (−411 m) este cel mai jos punct de pe uscat, dar nu este cel mai adânc punct al planetei. De ce?','["Pentru că adâncimi mult mai mari se găsesc în oceane (Fosa Marianelor, circa −11 022 m).","Pentru că Marea Moartă este, de fapt, un munte.","Pentru că −411 m este mai jos decât −11 022 m.","Pentru că oceanele nu au adâncimi reale."]','Nu confunda cel mai jos punct al uscatului cu cel mai adânc punct al planetei. Fosele oceanice coboară de zeci de ori mai mult decât Marea Moartă, deci recordul de adâncime este în ocean.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('f870bf32-2f4d-4762-bf40-2e382ae920df','9','geografie-fizica','published',3,124,1783400000000,1783400000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('f870bf32-2f4d-4762-bf40-2e382ae920df','ro','Două regiuni au aproape aceeași altitudine (în jur de 500 m), dar una are culmi largi și netede, iar cealaltă versanți înclinați cu vârfuri. Cum le clasificăm?','["Ambele sunt câmpii.","Ambele sunt munți.","Cea netedă este deal, iar cea înclinată este podiș.","Cea cu culmi netede este podiș, iar cea cu versanți înclinați este deal."]','Altitudinea nu ajunge; privește forma suprafeței. Podișul are culmi largi și netede, dealul are versanți înclinați — deci înfățișarea, nu doar înălțimea, le deosebește.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('7b25285f-38fe-4a33-8a68-1d8d67a4d716','9','geografie-fizica','published',1,125,1783400000000,1783400000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('7b25285f-38fe-4a33-8a68-1d8d67a4d716','ro','De ce munții sunt alcătuiți mai ales din roci dure, iar câmpiile din roci moi (nisipuri, pietrișuri, argile)?','["Pentru că rocile dure sunt mai ușoare decât cele moi.","Pentru că munții rezultă din încrețirea scoarței (roci dure cutate), iar câmpiile din acumularea sedimentelor aduse de fluvii (roci moi).","Pentru că în câmpii nu există niciun fel de roci.","Pentru că rocile moi se ridică singure și formează munți."]','Leagă tipul de rocă de modul de formare al treptei. Munții se nasc prin cutarea unor roci vechi și dure, iar câmpiile prin depunerea de sedimente afânate — de aici deosebirea de roci.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('2cb7d3d0-3dcb-437f-a7c5-a1a099797a7d','9','geografie-fizica','published',2,126,1783400000000,1783400000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('2cb7d3d0-3dcb-437f-a7c5-a1a099797a7d','ro','O câmpie s-a format prin acumularea materialelor aduse de un fluviu. Ce fel de forță a modelat-o în principal?','["O forță internă, de tipul orogenezei.","Vulcanismul din adâncul scoarței.","O forță externă: transportul și depunerea făcute de apa curgătoare.","Cutremurele de mare adâncime."]','Întreabă-te dacă fluviul acționează din interiorul sau de la suprafața scoarței. Apa curgătoare este un agent extern, iar acumularea sedimentelor ei este o modelare externă a reliefului.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('00868b73-5c20-4a55-8441-44d9ec0e13c9','9','geografie-fizica','published',0,127,1783400000000,1783400000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('00868b73-5c20-4a55-8441-44d9ec0e13c9','ro','Carpații s-au format în circa 150 de milioane de ani. Ce ne spune acest lucru despre formarea munților de încrețire?','["Că este un proces extrem de lent, desfășurat pe parcursul a milioane de ani.","Că munții apar brusc, într-o singură noapte.","Că munții se formează în doar câțiva ani.","Că munții nu se formează niciodată complet."]','Raportează durata la scara vieții unui om. Zecile și sutele de milioane de ani arată că înălțarea munților este un proces geologic foarte lent, imperceptibil în timpul unei vieți.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('cff90c95-7041-487e-8a53-a278c1ba57b7','9','geografie-fizica','published',1,128,1783400000000,1783400000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('cff90c95-7041-487e-8a53-a278c1ba57b7','ro','În faza de închidere a geosinclinalului apare avanfosa, în care se depun sedimentele erodate din munte. Ce relief ia naștere astfel, la marginea Carpaților?','["Un nou lanț de munți înalți.","Dealurile prealpine (Subcarpații).","O fosă oceanică adâncă.","Un vast platou vulcanic."]','Avanfosa este o depresiune de la poalele muntelui, umplută cu sedimente. Din aceste materiale acumulate se formează dealurile prealpine, adică Subcarpații.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('034a58d5-9d0e-445f-beff-5e5000e310ab','9','geografie-fizica','published',3,129,1783400000000,1783400000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('034a58d5-9d0e-445f-beff-5e5000e310ab','ro','Podișul Transilvaniei se află în interiorul arcului carpatic, iar Podișul Moldovei în afara lui. Cum le denumim după poziția față de lanțul muntos?','["Ambele sunt podișuri piemontane.","Ambele sunt câmpii de acumulare.","Transilvaniei este exterior, iar Moldovei interior.","Transilvaniei este un podiș interior, iar Moldovei un podiș exterior."]','Ghidează-te după cuvintele interior și exterior raportate la arcul carpatic. Fiind închis de munți, Podișul Transilvaniei este interior, iar cel al Moldovei, aflat în afara arcului, este exterior.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('ae3b55de-8817-4389-b9a7-d05795e4e791','9','geografie-fizica','published',2,130,1783400000000,1783400000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('ae3b55de-8817-4389-b9a7-d05795e4e791','ro','După milioane de ani de eroziune, un lanț muntos poate deveni o suprafață aproape plană (peneplenă sau pediplenă). Ce arată acest lucru despre relief?','["Că munții cresc la nesfârșit, fără oprire.","Că eroziunea nu are, de fapt, niciun efect asupra munților.","Că relieful este rezultatul luptei dintre forțele interne (care înalță) și cele externe (care netezesc).","Că munții respectivi nu au fost niciodată înalți."]','Dacă un munte poate ajunge aproape câmpie, înseamnă că ceva îl macină. Forțele interne l-au ridicat, iar cele externe l-au tocit — relieful de azi reflectă echilibrul dintre ele.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('1301df35-9cc1-4303-8388-205e95e0eb43','9','geografie-fizica','published',1,131,1783400000000,1783400000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('1301df35-9cc1-4303-8388-205e95e0eb43','ro','Ce exprimă adâncimea fragmentării unui relief?','["Suprafața totală ocupată de relief.","Cât de adânc au tăiat văile în relief, adică diferența de nivel dintre culme și vale.","Numărul de locuitori dintr-o regiune.","Altitudinea medie a întregii planete."]','Cuvântul-cheie este adâncimea: cât de jos au săpat râurile față de culmi. Adâncimea fragmentării este tocmai diferența de nivel dintre vârful interfluviului și fundul văii.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('79574318-c110-4ea6-a7bd-88023aed134d','9','geografie-fizica','published',0,132,1783400000000,1783400000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('79574318-c110-4ea6-a7bd-88023aed134d','ro','Într-o regiune, văile și culmile se succed foarte des, pe distanțe mici. Ce element morfologic are aici valori mari?','["Densitatea fragmentării.","Altitudinea absolută.","Adâncimea oceanelor.","Panta zero (teren perfect neted)."]','Fii atent la cuvântul des: cât de multe văi încap pe o suprafață. Când văile și culmile sunt numeroase și apropiate, densitatea fragmentării este mare.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('11ac57fd-533c-41bc-b8f1-9de059e0ca5f','9','geografie-fizica','published',2,133,1783400000000,1783400000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('11ac57fd-533c-41bc-b8f1-9de059e0ca5f','ro','Altitudinea medie a uscatului este de circa 875 m, iar adâncimea medie a oceanelor de circa 3794 m. Ce deducem comparând cele două valori?','["Că uscatul este, peste tot, mai jos decât fundul oceanelor.","Că cele două valori sunt, practic, egale.","Că adâncimile oceanice depășesc cu mult înălțimile medii ale uscatului.","Că oceanele sunt mai puțin adânci decât înălțimea medie a uscatului."]','Pune cele două numere alături: 3794 față de 875. Adâncimea medie a oceanelor este de peste patru ori mai mare decât altitudinea medie a uscatului.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('dcfb90d0-3211-4b81-9539-c07a54cdd8df','9','geografie-fizica','published',1,134,1783400000000,1783400000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('dcfb90d0-3211-4b81-9539-c07a54cdd8df','ro','Oceanul Pacific este cel mai întins ocean și adăpostește și cel mai adânc punct al planetei. Care este acesta?','["Fosa Puerto Rico.","Fosa Marianelor.","Fosa Java.","Fosa Fram."]','Asociază oceanul cel mai adânc cu fosa lui record. Fosa Marianelor, din Pacific, este cel mai adânc loc cunoscut al Terrei.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9e586d3a-f5d3-4b0c-b02c-afcb68e39adc','9','geografie-fizica','published',3,135,1783400000000,1783400000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9e586d3a-f5d3-4b0c-b02c-afcb68e39adc','ro','Un vulcan înalță un munte nou, dar în același timp ploaia și râurile îl tocesc. Ce ilustrează cel mai bine această situație?','["Că doar forțele externe modelează relieful.","Că doar forțele interne modelează relieful.","Că relieful, odată format, nu se mai schimbă niciodată.","Că relieful este modelat în același timp de forțe interne (care înalță) și externe (care netezesc)."]','Observă că două acțiuni opuse se petrec simultan. Vulcanul (forță internă) ridică relieful, iar apa (forță externă) îl macină — relieful este mereu rezultatul acestei confruntări.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('3d145540-3fd9-439e-b566-3477838ec5d0','9','geografie-fizica','published',0,136,1783400000000,1783400000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('3d145540-3fd9-439e-b566-3477838ec5d0','ro','O formă de relief depășește 1000 m altitudine, are vârfuri ascuțite și versanți abrupți. Cărei trepte îi aparține?','["Treapta munților.","Treapta câmpiilor.","Treapta podișurilor joase.","Fundul oceanului."]','Combină cele trei indicii: altitudine mare, vârfuri ascuțite, versanți abrupți. Ele descriu treapta cea mai înaltă a reliefului, adică munții.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('1218b58d-0e78-4d60-b5e4-8ae57755603e','9','geografie-fizica','published',2,137,1783400000000,1783400000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('1218b58d-0e78-4d60-b5e4-8ae57755603e','ro','De ce văile din munți sunt, de obicei, mult mai adânci decât cele din câmpie?','["Pentru că în câmpie nu curg deloc râuri.","Pentru că munții sunt alcătuiți exclusiv din roci moi.","Pentru că, la altitudini mari și pante abrupte, râurile au energie mare și taie adânc în rocă.","Pentru că în munți nu plouă niciodată."]','Gândește-te la puterea unei ape care curge repede, la vale. Pantele mari dau râurilor energie de eroziune ridicată, așa că ele adâncesc mult văile montane.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('02a038e6-9931-4d0f-9cc6-888456b5c6f8','9','geografie-fizica','published',1,138,1783400000000,1783400000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('02a038e6-9931-4d0f-9cc6-888456b5c6f8','ro','Ce deosebește, în esență, un podiș de un munte, chiar dacă amândouă pot depăși 800 m?','["Podișul se află întotdeauna sub nivelul mării.","Podișul are culmi largi și netede, cu roci mai ales orizontale, iar muntele are versanți abrupți și roci dure cutate.","Muntele este întotdeauna mai jos decât podișul.","Nu există nicio deosebire între ele."]','Nu te opri la altitudine; privește forma și dispunerea rocilor. Podișul este neted, cu straturi orizontale, iar muntele este cutat și abrupt — de aici deosebirea de fond.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('35429c79-e3e6-48ff-87d5-dacaaaab0f2c','9','geografie-fizica','published',0,139,1783400000000,1783400000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('35429c79-e3e6-48ff-87d5-dacaaaab0f2c','ro','Orogeneza este procesul de formare a munților. Ce mișcare a scoarței stă la baza ei?','["Încrețirea (cutarea) scoarței, prin comprimare.","Netezirea scoarței prin eroziune îndelungată.","Acumularea de sedimente în câmpii.","Topirea calotelor de gheață de la poli."]','Numele vine de la ideea de a naște munți. La bază stă comprimarea și încrețirea scoarței, care ridică straturile de roci în munți.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('e705b501-5bef-42b6-be0c-6d2e0e1fcfd1','9','geografie-fizica','published',3,140,1783400000000,1783400000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('e705b501-5bef-42b6-be0c-6d2e0e1fcfd1','ro','Domeniul continental ocupă doar 19% în emisfera sudică. Ce caracterizează, prin urmare, această emisferă?','["Este acoperită numai de uscat.","Nu are deloc oceane.","Are cel mai înalt munte de pe Terra.","Este dominată de ape, fiind mult mai săracă în uscat decât emisfera nordică."]','Dacă doar 19% este uscat, restul este apă. Emisfera sudică este, așadar, dominată de oceane, spre deosebire de cea nordică, bogată în continente.');
